      setSocketConnected(true, socket.id)
      recordSocketEvent({
        event: 'connect',
        direction: 'system',
        detail: socket.io?.engine?.transport?.name || null,
        socketId: socket.id
      })
      this._onConnect(socket.id)
    })

    socket.on('disconnect', (reason) => {
      console.log('[SocketManager] disconnected')
      setSocketConnected(false)
      recordSocketEvent({
        event: 'disconnect',
        direction: 'system',
        detail: reason || null,
        socketId: socket.id
      })
      this._onDisconnect()
    })

